  const THIS = [['ペン', 'a pen'], ['{本|ほん}', 'a book'], ['{犬|いぬ}', 'a dog'], ['りんご', 'an apple'], ['オレンジ', 'an orange'], ['{猫|ねこ}', 'a cat'], ['かばん', 'a bag'], ['たまご', 'an egg'], ['つくえ', 'a desk'], ['いす', 'a chair'], ['かさ', 'an umbrella'], ['ボール', 'a ball'], ['コップ', 'a cup'], ['ぼうし', 'a hat'], ['とけい', 'a clock']];
